def solve(stream, window_size):
    if not stream or window_size <= 0 or len(stream) < window_size:
        return 0.0
    window_sum = sum(stream[:window_size])
    max_sum = window_sum
    for i in range(window_size, len(stream)):
        window_sum += stream[i] - stream[i - window_size]
        if window_sum > max_sum:
            max_sum = window_sum
    return round(float(max_sum) / window_size, 2)
